key.query:
query SearchProducts($search: String!, $first: Int = 9) {
  products(first: $first, where: {search: $search}) {
    nodes {
      id
      databaseId
      name
      slug
      shortDescription
      image {
        sourceUrl
        mediaDetails {
          sizes {
            name
            sourceUrl
            __typename
          }
          __typename
        }
        __typename
      }
      ... on SimpleProduct {
        price
        regularPrice
        __typename
      }
      ... on VariableProduct {
        price
        regularPrice
        __typename
      }
      ... on ExternalProduct {
        price
        regularPrice
        __typename
      }
      ... on GroupProduct {
        price
        regularPrice
        __typename
      }
      ... on ProductWithPricing {
        price
        regularPrice
        __typename
      }
      __typename
    }
    __typename
  }
}
